//! The documentation index is GENERATED, and this is the check that keeps it
//! so.
//!
//! `docs/index.html` is a map of the documentation tree: a link to every
//! markdown file, its title, and its first sentence. It is generated by
//! `docs/build_index.py`, and the generator's default is `--check` — the
//! committed page is compared byte for byte with what the generator would
//! write, and THIS test runs that check. So a hand-edited index fails the
//! suite, and an index that has fallen behind the tree fails it too.
//!
//! The same discipline as `kingdoms/futhark_shapes/gen_tables.py`, and for
//! the same reason: a page that claims to be a map of the tree and is not is
//! worse than no page.

use std::process::Command;

#[test]
fn the_committed_index_is_what_the_generator_produces() {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
    let script = root.join("docs/build_index.py");
    assert!(script.exists(), "the generator is at {script:?}");
    // A missing `python3` is a FAILURE, not a skip: the check is part of the
    // contract, and a machine that cannot run it cannot keep the contract.
    let out = Command::new("python3")
        .arg(&script)
        .arg("--check")
        .current_dir(root)
        .output()
        .expect("python3 runs the index generator's check");
    assert!(
        out.status.success(),
        "the index generator's check failed:\n{}\n{}",
        String::from_utf8_lossy(&out.stdout),
        String::from_utf8_lossy(&out.stderr)
    );
}

/// The index is a page, and a page that does not parse is a page that does
/// not work: every link it offers is opened from it.
#[test]
fn the_index_is_a_well_formed_page() {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
    let page = std::fs::read_to_string(root.join("docs/index.html")).expect("the index page");
    assert!(page.starts_with("<!doctype html>"), "the page is an HTML document");
    assert!(page.trim_end().ends_with("</html>"), "the page is closed");
    // Every link is to a file that is there. A link to a file that moved is
    // the one failure a reader cannot forgive.
    let mut checked = 0usize;
    for href in page.split("href=\"").skip(1).map(|s| s.split('"').next().unwrap_or_default()) {
        if href.is_empty() || href.starts_with("http") {
            continue;
        }
        let path = root.join("docs").join(href);
        assert!(path.exists(), "the index links to {href:?}, which is not there");
        checked += 1;
    }
    assert!(checked > 50, "the index offers {checked} documents — it should offer the whole tree");
}
